type HomeCard={title:string;sub?:string;image:string;tag?:string;to:View};
function HomeFeatureCard({card,go,tall=false}:{card:HomeCard;go:(v:View)=>void;tall?:boolean}){return <button className={`gl-feature-card ${tall?'tall':''}`} onClick={()=>go(card.to)}><img src={card.image} alt=""/><span className="gl-card-shade"/><div>{card.tag&&<em>{card.tag}</em>}<b>{card.title}</b>{card.sub&&<small>{card.sub}</small>}</div></button>}
function HomeShelf({eyebrow,title,copy,cards,go,variant='standard'}:{eyebrow?:string;title:string;copy:string;cards:HomeCard[];go:(v:View)=>void;variant?:'today'|'events'|'picks'|'walk'|'culture'|'experience'|'people'|'shop'|'seasons'|'standard'}){return <section className={`gl-shelf gl-${variant}`}><header><span>{eyebrow}</span><h2>{title}</h2><p>{copy}</p><button onClick={()=>go(cards[0].to)}>もっと見る　›</button></header><div className="gl-shelf-grid">{cards.map((card,i)=><HomeFeatureCard key={i} card={card} go={go} tall={variant==='today'&&i===0}/>)}</div></section>}
function HomeSlideshow({go}:{go:(v:View)=>void}){const slides=[{tag:'ART',title:'町にひらく、現代美術の窓。',copy:'岐阜の路地とギャラリーを歩く。',image:homeImages.street,to:'walk' as View},{tag:'CRAFT',title:'紙と光がつくる、静かな景色。',copy:'美濃和紙の作り手を訪ねて。',image:homeImages.paper,to:'culture' as View},{tag:'PEOPLE',title:'手の記憶を、次の暮らしへ。',copy:'器をつくる人、その言葉に出会う。',image:homeImages.craft,to:'experience' as View}];const [active,setActive]=useState(0);useEffect(()=>{const timer=setInterval(()=>setActive(v=>(v+1)%slides.length),4800);return()=>clearInterval(timer)},[]);const move=(d:number)=>setActive(v=>(v+d+slides.length)%slides.length);return <section className="gl-slideshow" aria-label="注目のアートと工芸"><div className="gl-slide-viewport"><div className="gl-slide-track" style={{transform:`translateX(-${active*100}%)`}}>{slides.map(slide=><button key={slide.title} className="gl-slide-panel" style={{backgroundImage:`linear-gradient(90deg,#071827de,#07182738),url('${slide.image}')`}} onClick={()=>go(slide.to)}><span>{slide.tag} / FEATURE</span><h2>{slide.title}</h2><p>{slide.copy}</p><em>物語を読む　›</em></button>)}</div><button className="gl-slide-arrow prev" onClick={()=>move(-1)} aria-label="前のスライド">‹</button><button className="gl-slide-arrow next" onClick={()=>move(1)} aria-label="次のスライド">›</button><div className="gl-slide-progress"><i style={{width:`${((active+1)/slides.length)*100}%`}}/></div></div><div className="gl-slide-controls"><b>FEATURED STORIES</b>{slides.map((x,i)=><button key={x.title} className={i===active?'active':''} onClick={()=>setActive(i)} aria-label={`${i+1}枚目を表示`}><span>0{i+1}</span><small>{x.tag}</small></button>)}</div></section>}
function MobileTourismHome({go}:{go:(v:View)=>void}){const mosaic=[{title:'柳ケ瀬、朝のアート散歩',place:'岐阜市',image:homeImages.street,to:'walk' as View},{title:'紙と光のまち、美濃へ',place:'美濃市',image:homeImages.paper,to:'culture' as View},{title:'川辺で出会う、夏の表現',place:'長良川',image:homeImages.river,to:'eventlist' as View}];return <><Top title="GIFU ART & CRAFT" go={go}/><main className="content mobile-tourism-home"><HomeSlideshow go={go}/><section className="mobile-manifesto"><span>MOVING GIFU CITY</span><h1>岐阜のアートに、<br/>溺れたい。</h1><p>見るだけでなく、歩く。触れる。<br/>土地の文化を、自分の感覚で持ち帰る旅へ。</p></section><section className="mobile-editorial"><header><span>LOCAL STORIES</span><h2>いま、出会いたい岐阜。</h2></header><div className="mobile-mosaic">{mosaic.map((x,i)=><button key={x.title} className={i===0?'large':''} onClick={()=>go(x.to)}><img src={x.image} alt=""/><div><small>{x.place}</small><b>{x.title}</b></div></button>)}</div><button className="mobile-text-link" onClick={()=>go('search')}>場所や文化を探す　›</button></section><button className="mobile-wide-story" style={{backgroundImage:`linear-gradient(90deg,#071827e8,#07182742),url('${homeImages.festival}')`}} onClick={()=>go('eventlist')}><small>SEASON / EVENT</small><h2>祭りの熱に、<br/>町の記憶がよみがえる。</h2><span>季節の催しを見る　›</span></button><section className="mobile-experiences"><header><span>EXPERIENCE</span><h2>手で覚える、岐阜の文化。</h2></header><div>{[{title:'和傘づくり',image:'https://images.unsplash.com/photo-1558180700-0c1b2684f8cb?auto=format&fit=crop&w=700&q=82'},{title:'美濃焼ろくろ',image:homeImages.craft},{title:'美濃和紙',image:homeImages.paper}].map(x=><button key={x.title} onClick={()=>go('experience')}><img src={x.image} alt=""/><b>{x.title}</b><small>体験を見る ›</small></button>)}</div></section><button className="mobile-shop-banner" onClick={()=>go('shop')}><div><small>SHOP / PEOPLE</small><h2>作り手の手から、<br/>暮らしの中へ。</h2><span>岐阜の手仕事を見る　›</span></div><img src={homeImages.maker} alt="岐阜の作り手"/></button></main></>}
