 const today:HomeCard[]=[{tag:'自然',title:'新緑がまぶしい、付知峡で深呼吸を',sub:'中津川市',image:homeImages.mountain,to:'spot'},{tag:'人・暮らし',title:'古い町並みに灯るあかり、高山の夜散歩',sub:'高山市',image:homeImages.street,to:'walk'},{tag:'クラフト',title:'受け継がれる技と美濃焼、土と炎のものづくり',sub:'土岐市',image:homeImages.craft,to:'culture'},{tag:'食',title:'初夏の恵みをいただく、郷土の味',sub:'郡上市',image:homeImages.food,to:'spot'}];
