 const walk:HomeCard[]=[{title:'高山の古い町並みめぐり',sub:'約2時間　約3.0km',image:homeImages.street,to:'walk'},{title:'美濃のうだつと和紙の里へ',sub:'約2.5時間　約3.5km',image:homeImages.river,to:'walk'},{title:'川原町と長良川めぐり',sub:'約2時間　約2.8km',image:homeImages.mountain,to:'walk'},{title:'馬籠宿から妻籠宿へ中山道ハイク',sub:'約4時間　約6.0km',image:homeImages.forest,to:'walk'}];
