 const cultureWalk=[walk[0],walk[1],{...cultures[0],title:'町に残るアートを歩く',sub:'岐阜市',to:'walk' as View},{...cultures[1],title:'手仕事の町・美濃を歩く',sub:'美濃市',to:'walk' as View}];
